const ModelStorage=(()=>{
 const modelNames={m2m:'m2m100_418M',nllb:'nllb-200-distilled-600M'};
 const ocrKey=(preset,lang)=>`akai-beta-${preset}/${lang}.traineddata`;
 function ownsTranslation(url,engine){try{return new URL(url,location.href).pathname.split('/').includes(modelNames[engine])}catch{return false}}
 function ownsOcrUrl(url,preset){try{return new URL(url,location.href).pathname.match(new RegExp('/models/ocr/'+preset+'/(jpn|jpn_vert|eng|kor)\\.traineddata\\.gz$'))!==null}catch{return false}}
 function openDb(){return new Promise(resolve=>{if(!('indexedDB'in self)){resolve(null);return}const request=indexedDB.open('keyval-store');request.onupgradeneeded=()=>request.transaction.abort();request.onsuccess=()=>{const db=request.result;if(!db.objectStoreNames.contains('keyval')){db.close();resolve(null)}else resolve(db)};request.onerror=()=>resolve(null)})}
 async function ocrEntries(preset,remove=false){const db=await openDb();if(!db)return{count:0,bytes:0};return new Promise((resolve,reject)=>{let count=0,bytes=0;const tx=db.transaction('keyval',remove?'readwrite':'readonly'),store=tx.objectStore('keyval');for(const lang of ['jpn','jpn_vert','eng','kor']){const req=store.get(ocrKey(preset,lang));req.onsuccess=()=>{if(req.result!==undefined){count++;bytes+=req.result.byteLength||req.result.size||0;if(remove)store.delete(ocrKey(preset,lang))}}}tx.oncomplete=()=>{db.close();resolve({count,bytes})};tx.onerror=()=>{db.close();reject(tx.error)}})}
 async function cachedFiles(test,remove=false){let count=0,bytes=0,unknown=0,urls=[];if(!('caches'in self))return{count,bytes,unknown,urls};for(const name of await caches.keys()){if(name!=='transformers-cache'&&!name.startsWith('akai-beta-'))continue;const cache=await caches.open(name);for(const req of await cache.keys()){if(!test(req.url))continue;count++;urls.push(req.url);if(remove){await cache.delete(req);continue}const res=await cache.match(req),size=Number(res?.headers.get('content-length'));if(size>0)bytes+=size;else unknown++}}return{count,bytes,unknown,urls}}
 async function list(){const result=[];for(const engine of ['m2m','nllb']){const r=await cachedFiles(u=>ownsTranslation(u,engine));const valid=r.urls.filter(u=>new URL(u,location.href).origin==='https://huggingface.co');const ready=valid.some(u=>u.includes('encoder_model'))&&valid.some(u=>u.includes('decoder_model'))&&valid.some(u=>u.endsWith('config.json'))&&valid.some(u=>u.endsWith('tokenizer.json'));result.push({id:engine,...r,state:!r.count?'미저장':ready?'모델 파일 저장됨':'일부 파일만 저장됨'})}
 for(const preset of ['fast','best']){const r=await ocrEntries(preset),cached=await cachedFiles(u=>ownsOcrUrl(u,preset));result.push({id:preset,count:r.count+cached.count,bytes:r.bytes+cached.bytes,unknown:cached.unknown,state:r.count||cached.count?'캐시 있음':'캐시 없음'})}return result}
 async function remove(engine){if(engine==='all'){for(const e of ['m2m','nllb','fast','best'])await remove(e);return}if(modelNames[engine])await cachedFiles(u=>ownsTranslation(u,engine),true);else if(['fast','best'].includes(engine)){await ocrEntries(engine,true);await cachedFiles(u=>ownsOcrUrl(u,engine),true)}else throw Error('관리 대상이 아닌 엔진입니다.')}
 return {list,remove,ownsTranslation,ownsOcrUrl,ocrKey};
})();
